// One reflector class: DNS ANY by default.
const reqBytes = 40;        // attacker query size
const respBytes = 1700;     // reflector reply size (try 51200 for memcached)
const reflectors = 10000;   // open servers the attacker abuses
const qpsPerReflector = 5;  // queries the attacker sends to each, per second

const factor = respBytes / reqBytes;
const attackerBps = reflectors * qpsPerReflector * reqBytes * 8;
const victimBps = reflectors * qpsPerReflector * respBytes * 8;

const gbps = (bps) => (bps / 1e9).toFixed(2);
console.log('amplification factor: ' + factor.toFixed(1) + 'x');
console.log('attacker uplink: ' + gbps(attackerBps) + ' Gbps');
console.log('victim flood:    ' + gbps(victimBps) + ' Gbps');
